var sanitized = ImmutableList.CreateBuilder<DockBandSettings>();
var seen = new HashSet<(string ProviderId, string CommandId)>(StringComparer.OrdinalIgnoreCase);
foreach (var band in bands)
{
    var key = (band.ProviderId, band.CommandId);
    var topLevel = _topLevelCommandManager.LookupDockBand(band.CommandId);
    if (topLevel is null || !seen.Add(key))
    {
        repaired = true;
        continue;
    }
    sanitized.Add(band);
    newBands.Add(CreateBandItem(band, topLevel.ItemViewModel));
}
if (repaired) PersistSanitizedBands(sanitized.ToImmutable());

IEnumerable<DockBandSettings> CanonicalizeBands(IEnumerable<DockBandSettings> source)
    => source.GroupBy(b => (b.ProviderId, b.CommandId), StringComparer.OrdinalIgnoreCase)
             .Select(g => g.First());

